CREATE OR REPLACE FUNCTION public.post_heal(p_location uuid, p_target_user uuid DEFAULT NULL::uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.characters%rowtype; d public.characters%rowtype; v_staff boolean;
  v_cost int := 20; heal int; old_v int; gain int; new_v int; outcome text; v_self boolean; v_test boolean;
begin
  if auth.uid() is null then raise exception 'non autenticato'; end if;
  select l.is_test into v_test from public.locations l where l.id=p_location and l.is_active;
  if v_test is null then raise exception 'luogo non valido'; end if;
  v_staff := public.is_staff();
  if v_test and not public._puo_test_room() then raise exception 'La Test Room è riservata allo staff'; end if;
  select * into a from public.characters where user_id=auth.uid() limit 1;
  if a.id is null then raise exception 'nessun personaggio associato'; end if;
  if not v_staff and not (coalesce(a.corporation,'') ~* 'medic') then
    raise exception 'Solo un ninja medico (corporazione Medico) può curare con il Palmo Curativo.';
  end if;
  if not v_staff and not exists (
    select 1 from public.character_abilities ca
      join public.clan_techniques t on t.id = ca.technique_id
     where ca.character_id = a.id and ca.state = 'attiva'
       and t.name = 'Palmo Curativo' and t.macro = 'abilita'
  ) then
    raise exception 'Serve la tecnica Palmo Curativo, abilità dei medici: si apprende dalla Scheda.';
  end if;
  if coalesce(a.vita,0) <= 0 then raise exception 'Sei fuori combattimento: non puoi curare'; end if;
  if p_target_user is null or p_target_user = a.user_id then
    d := a; v_self := true;
  else
    select * into d from public.characters where user_id=p_target_user limit 1;
    if d.id is null then raise exception 'bersaglio non valido'; end if;
    v_self := false;
    if not v_staff and not exists (select 1 from public.presence pr where pr.user_id=d.user_id and pr.location_id=p_location) then
      raise exception 'Il bersaglio non è presente in questa scena';
    end if;
  end if;
  if coalesce(a.chakra_max,0) > 0 and coalesce(a.chakra,0) < v_cost then
    raise exception 'Chakra insufficiente: servono % (ne hai %)', v_cost, coalesce(a.chakra,0);
  end if;
  heal := greatest(5, (coalesce(a.mente,0)+coalesce(a.ninjutsu,0))/3);
  old_v := coalesce(d.vita,0);
  gain := least(heal, greatest(0, coalesce(d.vita_max,0)-old_v));
  if gain <= 0 and not v_test then
    raise exception '%', (case when v_self then 'Sei già al massimo dei PV' else d.name||' è già al massimo dei PV' end);
  end if;
  if v_test then
    new_v := old_v + gain;
  else
    perform set_config('app.allow_vita_delta','1', true);
    update public.characters set vita = old_v + gain where id = d.id returning vita into new_v;
    if coalesce(a.chakra_max,0) > 0 and v_cost > 0 then
      perform set_config('app.allow_chakra_delta','1', true);
      update public.characters set chakra = greatest(0, coalesce(chakra,0) - v_cost) where id = a.id;
    end if;
  end if;
  if v_self then
    outcome := a.name||' usa il Palmo Curativo su sé stesso e recupera '||gain||' PV. (PV: '||new_v||'/'||coalesce(d.vita_max,0)||')  〈−'||v_cost||' chakra · turno speso〉';
  else
    outcome := a.name||' cura '||d.name||' col Palmo Curativo: +'||gain||' PV. (PV di '||d.name||': '||new_v||'/'||coalesce(d.vita_max,0)||')  〈−'||v_cost||' chakra · turno speso〉';
  end if;
  if v_test then
    outcome := outcome||(case when gain <= 0 then '  〈era già al massimo dei PV〉' else '' end)||'  〈prova: nessun valore è stato modificato〉';
  end if;
  insert into public.messages(location_id, character_id, author_name, kind, sender_user, recipient_user, recipient_name, body)
    values (p_location, a.id, a.name, 'cura', auth.uid(),
            case when v_self then null else d.user_id end,
            case when v_self then null else d.name end,
            outcome);
  insert into public.presence(user_id, last_seen, location_id) values (auth.uid(), now(), p_location)
    on conflict (user_id) do update set last_seen = now(), location_id = excluded.location_id;
  return outcome;
end; $function$

