  end if;
  heal := greatest(5, (coalesce(a.mente,0)+coalesce(a.ninjutsu,0))/3);
  old_v := coalesce(d.vita,0);
  gain := least(heal, greatest(0, coalesce(d.vita_max,0)-old_v));
  if gain <= 0 and not v_test then
    raise exception '%', (case when v_self then 'Sei già al massimo dei PV' else d.name||' è già al massimo dei PV' end);
  end if;
  if v_test then
    new_v := old_v + gain;
  else
    perform set_config('app.allow_vita_delta','1', true);
    update public.characters set vita = old_v + gain where id = d.id returning vita into new_v;
    if coalesce(a.chakra_max,0) > 0 and v_cost > 0 then
      perform set_config('app.allow_chakra_delta','1', true);
      update public.characters set chakra = greatest(0, coalesce(chakra,0) - v_cost) where id = a.id;
    end if;
  end if;
  if v_self then
    outcome := a.name||' usa il Palmo Curativo su sé stesso e recupera '||gain||' PV. (PV: '||new_v||'/'||coalesce(d.vita_max,0)||')  〈−'||v_cost||' chakra · turno speso〉';
  else
    outcome := a.name||' cura '||d.name||' col Palmo Curativo: +'||gain||' PV. (PV di '||d.name||': '||new_v||'/'||coalesce(d.vita_max,0)||')  〈−'||v_cost||' chakra · turno speso〉';
  end if;
  if v_test then
    outcome := outcome||(case when gain <= 0 then '  〈era già al massimo dei PV〉' else '' end)||'  〈prova: nessun valore è stato modificato〉';
  end if;
  insert into public.messages(location_id, character_id, author_name, kind, sender_user, recipient_user, recipient_name, body)
    values (p_location, a.id, a.name, 'cura', auth.uid(),
            case when v_self then null else d.user_id end,
            case when v_self then null else d.name end,
            outcome);
  insert into public.presence(user_id, last_seen, location_id) values (auth.uid(), now(), p_location)
    on conflict (user_id) do update set last_seen = now(), location_id = excluded.location_id;
  return outcome;
end; $function$

