CREATE OR REPLACE FUNCTION combat_v2_elemental_internal.other_consumer_options(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE aid uuid:=(p#>>'{viewer,actor_id}')::uuid;sid uuid:=(p#>>'{context,activity_id}')::uuid;
 a public.combat_v2_actors%ROWTYPE;c combat_consumer_private.activities%ROWTYPE;
 tid uuid;target uuid;profile jsonb;q jsonb;offer jsonb;offers jsonb:=coalesce(p->'offers','[]');push boolean;label text;
BEGIN
 IF aid IS NULL OR sid IS NULL OR p->>'status' IS DISTINCT FROM 'ready' THEN RETURN p;END IF;
 SELECT * INTO a FROM public.combat_v2_actors WHERE id=aid AND session_id=sid AND controller_user=exam_regia_private.current_principal() AND state='attivo';
 SELECT * INTO c FROM combat_consumer_private.activities WHERE session_id=sid AND phase='action' AND turn_actor_id=aid;
 IF a.id IS NULL OR c.session_id IS NULL OR NOT combat_effects_private.session_allowed(sid) THEN RETURN p;END IF;
 SELECT actor_id INTO target FROM combat_consumer_private.members WHERE session_id=sid AND actor_id<>aid;
 FOR tid IN SELECT technique_id FROM combat_v2_elemental_internal.other_gates WHERE enabled ORDER BY technique_id LOOP
  profile:=combat_v2_elemental_internal.technique_profile_v1(tid);
  IF combat_v2_elemental_internal.other_preset_ready(aid,tid) THEN
   offers:=offers||jsonb_build_array(combat_consumer_private.offer_exchange(sid,aid,NULL,(p#>>'{context,scene_version}')::integer,
    'control','Prepara prova: '||(profile->>'name'),jsonb_build_object('other_operation','staff_profile','technique_id',tid)));
  END IF;
  q:=combat_v2_elemental_internal.other_quote(aid,tid);
  IF q IS NULL OR target IS NULL OR EXISTS(SELECT 1 FROM combat_panel_private.multiplication_formations WHERE actor_id=target AND state='active') THEN CONTINUE;END IF;
  IF NOT combat_v2_elemental_internal.other_target_visible(aid,target,CASE WHEN tid='72cbe1fb-34c8-44c7-a053-0014b4894b3e'::uuid THEN combat_v2_elemental_internal.scarica_contact_range(aid,target) ELSE (profile->>'range_m')::numeric END) THEN CONTINUE;END IF;
  FOR push IN SELECT false UNION ALL SELECT true WHERE tid='d5605069-b381-41ad-8e6a-9c24a314c58f'::uuid LOOP
   label:=(profile->>'name')||' · '||(q->>'total')||' chakra'||CASE WHEN tid='d5605069-b381-41ad-8e6a-9c24a314c58f'::uuid THEN
    CASE WHEN push THEN ' · spinge se colpisce' ELSE ' · senza spinta' END ELSE '' END;
   offer:=combat_consumer_private.offer_exchange(sid,aid,target,(p#>>'{context,scene_version}')::integer,'declare',label,
    jsonb_build_object('intent',jsonb_build_object('kind','attacco','ability_source','clan','ability_id',tid,'target_actor',target),
     'other_push_requested',push));
   offers:=offers||jsonb_build_array(offer);
  END LOOP;
 END LOOP;
 RETURN combat_v2_taijutsu_internal.consumer_options(jsonb_set(p,'{offers}',offers));
END $function$

