CREATE OR REPLACE FUNCTION combat_v2_elemental_internal.other_master_options(p_context uuid, p_expected bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c combat_panel_private.contexts%ROWTYPE;tid uuid;o combat_panel_private.offers%ROWTYPE;profile jsonb;gid uuid;
BEGIN
 c:=combat_panel_private.owned_context(p_context,p_expected);
 IF c.activity_kind<>'master_v2' OR c.command_actor_id IS NULL OR NOT combat_effects_private.session_allowed(c.activity_id) THEN RETURN;END IF;
 FOR tid IN SELECT technique_id FROM combat_v2_elemental_internal.other_gates WHERE enabled LOOP
  profile:=combat_v2_elemental_internal.technique_profile_v1(tid);
  IF combat_v2_elemental_internal.other_preset_ready(c.command_actor_id,tid) AND NOT EXISTS(SELECT 1 FROM combat_panel_private.offers
   WHERE context_id=c.id AND context_version=c.context_version AND state='offered' AND source_payload->>'dispatch'='other_control'
    AND source_payload->>'technique_id'=tid::text) THEN
   PERFORM combat_panel_private.create_offer(c.id,c.context_version,'control','control','Prepara prova: '||(profile->>'name'),false,
    jsonb_build_object('adapter','master_v2','dispatch','other_control','other_operation','staff_profile','technique_id',tid));
  END IF;
 END LOOP;
 FOR o IN SELECT * FROM combat_panel_private.offers WHERE context_id=c.id AND context_version=c.context_version AND state='offered'
  AND source_payload->>'dispatch'='action' AND source_payload->>'ability_source'='clan'
  AND source_payload->>'ability_id'='d5605069-b381-41ad-8e6a-9c24a314c58f' LOOP
  IF combat_v2_elemental_internal.other_profile(c.command_actor_id,'d5605069-b381-41ad-8e6a-9c24a314c58f') IS NULL THEN CONTINUE;END IF;
  IF EXISTS(SELECT 1 FROM combat_panel_private.choice_options WHERE offer_id=o.id AND source_payload?'other_push_requested') THEN CONTINUE;END IF;
  gid:=combat_panel_private.add_group(o.id,'Spinta su colpo pieno','generic','single',1,1);
  PERFORM combat_panel_private.add_choice(gid,'Non spingere',jsonb_build_object('other_push_requested',false));
  PERFORM combat_panel_private.add_choice(gid,'Spingi fino a 3 m',jsonb_build_object('other_push_requested',true));
 END LOOP;
 PERFORM combat_v2_taijutsu_internal.master_options(c.id,c.context_version);
END $function$

