CREATE OR REPLACE FUNCTION combat_v2_elemental_internal.other_control_target(p_adapter text, p_offer uuid, p_actor uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.combat_v2_actors%ROWTYPE;co combat_consumer_private.offers%ROWTYPE;ctx combat_consumer_private.activities%ROWTYPE;
 mo combat_panel_private.offers%ROWTYPE;c combat_panel_private.contexts%ROWTYPE;payload jsonb;tid uuid;
BEGIN
 SELECT * INTO STRICT a FROM public.combat_v2_actors WHERE id=p_actor AND actor_kind='pg' AND controller_user=exam_regia_private.current_principal();
 PERFORM combat_effects_private.lock_context(a.session_id);
 IF p_adapter='ordinary_v2' THEN
  SELECT * INTO STRICT ctx FROM combat_consumer_private.activities WHERE session_id=a.session_id FOR UPDATE;
  SELECT * INTO STRICT co FROM combat_consumer_private.offers WHERE id=p_offer FOR UPDATE;
  IF co.session_id IS DISTINCT FROM a.session_id OR co.principal_character_id IS DISTINCT FROM a.character_id
   OR co.operation<>'control' OR co.state<>'offered' OR co.context_version IS DISTINCT FROM ctx.context_version
   OR co.exchange_id IS DISTINCT FROM ctx.exchange_id THEN RAISE EXCEPTION 'other_control_offer_invalid';END IF;
  payload:=co.source_payload;tid:=(payload->>'technique_id')::uuid;
  IF payload IS DISTINCT FROM jsonb_build_object('other_operation','staff_profile','technique_id',tid) THEN RAISE EXCEPTION 'other_control_payload_invalid';END IF;
 ELSIF p_adapter='master_v2' THEN
  SELECT * INTO STRICT mo FROM combat_panel_private.offers WHERE id=p_offer AND principal_user=exam_regia_private.current_principal() FOR UPDATE;
  c:=combat_panel_private.owned_context(mo.context_id,mo.context_version);
  IF c.activity_kind<>'master_v2' OR c.activity_id IS DISTINCT FROM a.session_id OR c.command_actor_id IS DISTINCT FROM a.id
   OR mo.actor_id IS DISTINCT FROM a.id OR mo.kind<>'control' OR mo.operation<>'control' OR mo.state<>'offered'
   OR mo.source_fingerprint IS DISTINCT FROM c.source_fingerprint OR mo.scene_version IS DISTINCT FROM c.scene_version THEN RAISE EXCEPTION 'other_control_offer_invalid';END IF;
  payload:=mo.source_payload;tid:=(payload->>'technique_id')::uuid;
  IF payload IS DISTINCT FROM jsonb_build_object('adapter','master_v2','dispatch','other_control','other_operation','staff_profile','technique_id',tid)
   THEN RAISE EXCEPTION 'other_control_payload_invalid';END IF;
 ELSE RAISE EXCEPTION 'other_control_adapter_invalid';END IF;
 IF tid IN ('f1440a58-ee95-53dc-8ed5-a53543d970ce'::uuid,'f0fdbc8e-5cf3-5c9b-af2a-e52869fa8dfc'::uuid,'65719592-7de9-5aa1-8d59-e8da2338d45b'::uuid,'96927a19-9908-59da-9f17-2611e031bd8d'::uuid,'9ac77d79-9894-5388-9753-70538ac5eaa3'::uuid) THEN
  IF NOT combat_v2_taijutsu_internal.preset_ready(a.id,tid) THEN RAISE EXCEPTION 'other_control_not_available';END IF;
 ELSIF NOT combat_v2_elemental_internal.other_preset_ready(a.id,tid) THEN RAISE EXCEPTION 'other_control_not_available';END IF;
 RETURN tid;
