     hyuga_juken IS NOT NULL OR hyuga_profile IS NOT NULL OR fireball_profile IS NOT NULL
     OR kind<>'ninjutsu' OR base<>0
   ) THEN RAISE EXCEPTION 'nara_native_profile_conflict' USING ERRCODE='55000'; END IF;
