 SELECT * INTO STRICT r FROM public.combat_v2_rounds WHERE id=p_round FOR UPDATE;
 IF r.phase<>'risoluzione' OR EXISTS(SELECT 1 FROM public.combat_v2_round_reports WHERE round_id=r.id)
  OR EXISTS(SELECT 1 FROM public.combat_v2_declarations WHERE round_id=r.id
   AND kind IN ('attacco','movimento','utilita','passa') AND state NOT IN ('risolta','superflua','annullata')) THEN
