   END IF;
   IF t.state='ended' AND NOT EXISTS(SELECT 1 FROM combat_effects_private.effect_events WHERE event_key=receipt_key) THEN
    IF EXISTS(SELECT 1 FROM combat_effects_private.effect_applications WHERE session_id=r.session_id
