CREATE OR REPLACE FUNCTION combat_panel_private.narrative_outcome_facts(p_outcome jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE result jsonb:='{}'::jsonb; escape jsonb; effect jsonb; damage numeric;
 intercepted boolean; spent boolean; success boolean; canonical text;
BEGIN
 IF jsonb_typeof(p_outcome) IS DISTINCT FROM 'object' THEN
   RAISE EXCEPTION 'panel_narrative_outcome_invalid' USING ERRCODE='22023'; END IF;
 escape:=p_outcome->'immobilization_escape';
 IF escape IS NOT NULL THEN
   IF escape->>'schema_version' IS DISTINCT FROM 'immobilization-escape/1'
     OR jsonb_typeof(escape->'attempted') IS DISTINCT FROM 'boolean' THEN
     RAISE EXCEPTION 'panel_narrative_escape_invalid' USING ERRCODE='22023'; END IF;
   IF (escape->>'attempted')::boolean THEN
     IF jsonb_typeof(escape->'success') IS DISTINCT FROM 'boolean'
       OR jsonb_typeof(p_outcome->'still_immobilized') IS DISTINCT FROM 'boolean' THEN
       RAISE EXCEPTION 'panel_narrative_escape_invalid' USING ERRCODE='22023'; END IF;
     result:=jsonb_build_object('escape',jsonb_build_object('attempted',true,
       'hold_released',escape->'success','still_immobilized',p_outcome->'still_immobilized'));
   ELSE
     IF escape->>'reason' IS NULL OR escape->>'reason' NOT IN ('actor_inoperative','hold_already_ended') THEN
       RAISE EXCEPTION 'panel_narrative_escape_invalid' USING ERRCODE='22023'; END IF;
     result:=jsonb_build_object('escape',jsonb_build_object('attempted',false,'reason',escape->'reason'));
   END IF;
   RETURN result;
 END IF;
 effect:=p_outcome->'multiplication_effect';
 IF effect IS NOT NULL AND (jsonb_typeof(effect) IS DISTINCT FROM 'object'
   OR jsonb_typeof(effect->'copy_intercepted') IS DISTINCT FROM 'boolean'
   OR jsonb_typeof(effect->'defense_spent_on_copy') IS DISTINCT FROM 'boolean') THEN
   RAISE EXCEPTION 'panel_narrative_copy_effect_invalid' USING ERRCODE='22023'; END IF;
 intercepted:=coalesce((effect->>'copy_intercepted')::boolean,false);
 spent:=coalesce((effect->>'defense_spent_on_copy')::boolean,false);
 canonical:=p_outcome->>'canonical_outcome';
 IF canonical IS NOT NULL AND canonical NOT IN ('negato_sostituzione','reazione_spesa_su_copia') THEN
   RAISE EXCEPTION 'panel_narrative_canonical_invalid' USING ERRCODE='22023'; END IF;
 IF p_outcome ? 'damage_applied' THEN
   IF jsonb_typeof(p_outcome->'damage_applied') IS DISTINCT FROM 'number'
     OR (p_outcome->>'damage_applied')::numeric<0 THEN
     RAISE EXCEPTION 'panel_narrative_damage_invalid' USING ERRCODE='22023'; END IF;
   damage:=(p_outcome->>'damage_applied')::numeric;
 END IF;
 IF p_outcome ? 'success' THEN
   IF jsonb_typeof(p_outcome->'success') IS DISTINCT FROM 'boolean' THEN
     RAISE EXCEPTION 'panel_narrative_success_invalid' USING ERRCODE='22023'; END IF;
   success:=(p_outcome->>'success')::boolean;
 END IF;
 IF intercepted AND (damage IS DISTINCT FROM 0 OR success IS DISTINCT FROM false) THEN
   RAISE EXCEPTION 'panel_narrative_copy_damage_conflict' USING ERRCODE='22023'; END IF;
 IF canonical='negato_sostituzione' AND (coalesce(damage,0)<>0 OR coalesce(success,false)) THEN
   RAISE EXCEPTION 'panel_narrative_substitution_conflict' USING ERRCODE='22023'; END IF;
 IF p_outcome ? 'multiplication_predefense' THEN
   IF p_outcome#>>'{multiplication_predefense,contract}' IS DISTINCT FROM 'multiplication-resume/1'
    OR p_outcome#>>'{multiplication_predefense,result}' NOT IN ('copy_hit','vanished_copy_out_of_range','original_out_of_range')
    OR p_outcome#>'{multiplication_predefense,defense_required}' IS DISTINCT FROM 'false'::jsonb
    OR damage IS DISTINCT FROM 0 OR success IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'panel_narrative_copy_outcome_invalid' USING ERRCODE='22023'; END IF;
   IF p_outcome#>>'{multiplication_predefense,result}' IN ('vanished_copy_out_of_range','original_out_of_range') THEN
    result:=result||jsonb_build_object('attack_result',p_outcome#>'{multiplication_predefense,result}',
      'copies',jsonb_build_object('intercepted',false,'defense_spent',false));
    RETURN result;
   END IF;
 END IF;
 IF p_outcome->>'reason'='bersaglio_gia_fuori' THEN
   result:=result||jsonb_build_object('attack_result','target_already_inoperative');
 ELSIF intercepted THEN
   result:=result||jsonb_build_object('attack_result','copy_intercepted');
 ELSIF canonical='negato_sostituzione' THEN
   result:=result||jsonb_build_object('attack_result','substitution_negated');
 ELSIF success IS NOT NULL AND damage IS NOT NULL THEN
   result:=result||jsonb_build_object('attack_result',CASE WHEN success THEN 'hit' WHEN damage>0 THEN 'grazed' ELSE 'missed' END);
 END IF;
 IF effect IS NOT NULL OR canonical='reazione_spesa_su_copia' THEN
   result:=result||jsonb_build_object('copies',jsonb_build_object('intercepted',intercepted,
     'defense_spent',spent OR coalesce(canonical='reazione_spesa_su_copia',false)));
 END IF;
 IF effect->>'tactics_contract'='multiplication-tactics/1' THEN
   IF jsonb_typeof(effect->'assault_bonus') IS DISTINCT FROM 'number'
