CREATE OR REPLACE FUNCTION combat_panel_private.round_details_from_source(p_source jsonb, p_roster jsonb, p_offers jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE d jsonb; item jsonb; child jsonb; report jsonb; outcome jsonb; actor_name text; target_name text;
 declarations jsonb:='[]'; targets jsonb; coverage jsonb; lines jsonb:='[]'; label text; rating text; offer_id uuid;
 rid uuid; report_view jsonb:=NULL; line text; target_id text; suiton jsonb; forced jsonb; elemental jsonb; offensive jsonb; result_item jsonb; effect_targets jsonb;
BEGIN
 rid:=(p_source#>>'{round,id}')::uuid; IF rid IS NULL THEN RETURN NULL; END IF;
 FOR d IN SELECT value FROM jsonb_array_elements(coalesce(p_source->'declarations','[]')) LOOP
   SELECT value->>'display_name' INTO actor_name FROM jsonb_array_elements(p_roster) WHERE value->>'actor_id'=d->>'actor_id';
   IF actor_name IS NULL THEN CONTINUE; END IF;
   targets:='[]'; coverage:='[]';
   FOR item IN SELECT value FROM jsonb_array_elements(coalesce(d->'targets','[]')) LOOP
     SELECT value->>'display_name' INTO target_name FROM jsonb_array_elements(p_roster) WHERE value->>'actor_id'=item->>'target_actor_id';
     IF target_name IS NOT NULL THEN targets:=targets||jsonb_build_array(jsonb_build_object('actor_id',item->'target_actor_id','display_name',target_name)); END IF;
   END LOOP;
   FOR item IN SELECT value FROM jsonb_array_elements(coalesce(d->'coverage','[]')) LOOP
     SELECT value->>'display_name' INTO target_name FROM jsonb_array_elements(p_roster) WHERE value->>'actor_id'=item->>'protected_actor_id';
     IF target_name IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coverage) WHERE value->>'actor_id'=item->>'protected_actor_id') THEN
       coverage:=coverage||jsonb_build_array(jsonb_build_object('actor_id',item->'protected_actor_id','display_name',target_name));
     END IF;
   END LOOP;
   label:=coalesce(nullif(d#>>'{choice,ability_name}',''),CASE coalesce(d#>>'{choice,reaction}',d->>'kind')
     WHEN 'attacco' THEN 'Attacco' WHEN 'movimento' THEN 'Movimento' WHEN 'utilita' THEN 'Azione non offensiva'
     WHEN 'passa' THEN 'Passa' WHEN 'schivata' THEN 'Schivata' WHEN 'parata' THEN 'Parata'
     WHEN 'sostituzione' THEN 'Sostituzione' WHEN 'nessuna' THEN 'Nessuna difesa' ELSE 'Difesa' END);
   rating:=NULL;
   IF jsonb_typeof(d#>'{rating,value}')='number' THEN
     rating:='Valutazione '||(d#>>'{rating,value}')||CASE WHEN length(coalesce(d#>>'{rating,reason}',''))>0 THEN ' · '||(d#>>'{rating,reason}') ELSE '' END;
   END IF;
   SELECT (value->>'offer_id')::uuid INTO offer_id FROM jsonb_array_elements(p_offers)
     WHERE value->>'declaration_id'=d->>'id' LIMIT 1;
   declarations:=declarations||jsonb_build_array(jsonb_build_object('declaration_id',d->'id','actor_id',d->'actor_id',
     'display_name',actor_name,'kind',d->'kind','label',label,'text',coalesce(d->>'text',''),
     'targets',targets,'coverage',coverage,'rating_label',rating,'rating_offer_id',offer_id));
 END LOOP;
 report:=p_source->'report';
 IF jsonb_typeof(report)='object' AND report->>'id' IS NOT NULL THEN
   FOR d IN SELECT value FROM jsonb_array_elements(coalesce(report#>'{mechanics,declarations}','[]')) LOOP
     IF d->>'kind' IN ('difesa','nessuna') THEN
       -- Solo fatti Scudo congelati dal server prima dell'hash del report.
       -- Le altre difese conservano la proiezione preesistente.
       IF d->>'kind'='difesa' AND d->>'state'='risolta'
         AND d#>>'{scudo_facts,scudo_server,name}'='Scudo di terra'
         AND d#>>'{scudo_facts,scudo_server,coverage}'='self'
         AND d#>'{scudo_facts,scudo_server,persistent_cover}'='false'::jsonb THEN
         SELECT value->>'display_name' INTO actor_name FROM jsonb_array_elements(p_roster) WHERE value->>'actor_id'=d->>'actor';
         IF actor_name IS NOT NULL THEN
           line:=actor_name||' · Scudo di terra: difesa singola personale';
           IF jsonb_typeof(d#>'{cost,chakra}')='number' THEN
             line:=line||' · costo '||(d#>>'{cost,chakra}')||' chakra';
           END IF;
           lines:=lines||jsonb_build_array(line);
         END IF;
       END IF;
       CONTINUE;
     END IF;
     SELECT value->>'display_name' INTO actor_name FROM jsonb_array_elements(p_roster) WHERE value->>'actor_id'=d->>'actor';
     IF actor_name IS NULL THEN CONTINUE; END IF;
     outcome:=d->'outcome';
     IF jsonb_typeof(outcome->'children')='array' THEN
       FOR child IN SELECT value FROM jsonb_array_elements(outcome->'children') LOOP
         SELECT value->>'display_name' INTO target_name FROM jsonb_array_elements(p_roster) WHERE value->>'actor_id'=child->>'target_actor_id';
         IF target_name IS NULL THEN CONTINUE; END IF;
         line:=actor_name||' → '||target_name;
         IF jsonb_typeof(child->'success')='boolean' THEN line:=line||CASE WHEN (child->>'success')::boolean THEN ': attacco riuscito' ELSE ': attacco non riuscito' END; END IF;
         IF jsonb_typeof(child->'damage_applied')='number' THEN line:=line||' · danno '||(child->>'damage_applied'); END IF;
         line:=line||combat_panel_private.catalog_result_label_v1(child);
         line:=line||combat_panel_private.multiplication_result_label(child);
         lines:=lines||jsonb_build_array(line);
       END LOOP;
     ELSE
       line:=actor_name||' · '||CASE d->>'kind' WHEN 'movimento' THEN 'Movimento' WHEN 'passa' THEN 'Passa' WHEN 'utilita' THEN 'Azione non offensiva' ELSE 'Attacco' END;
       SELECT value->>'display_name' INTO target_name FROM jsonb_array_elements(p_roster) WHERE value->>'actor_id'=d->>'target';
       IF d->>'target' IS NOT NULL AND target_name IS NULL THEN CONTINUE; END IF;
       IF target_name IS NOT NULL THEN line:=line||' → '||target_name; END IF;
       IF jsonb_typeof(outcome->'movement_m')='number' THEN line:=line||': '||(outcome->>'movement_m')::numeric::integer::text||' m'; END IF;
       IF jsonb_typeof(outcome->'success')='boolean' THEN line:=line||CASE WHEN (outcome->>'success')::boolean THEN ': riuscito' ELSE ': non riuscito' END; END IF;
       IF jsonb_typeof(outcome->'damage_applied')='number' THEN line:=line||' · danno '||(outcome->>'damage_applied'); END IF;
       line:=line||combat_panel_private.catalog_result_label_v1(outcome);
       line:=line||combat_panel_private.multiplication_result_label(outcome);
       line:=line||combat_panel_private.immobilization_result_label(outcome);
       lines:=lines||jsonb_build_array(line);
     END IF;
     lines:=lines||combat_panel_private.catalog_lifecycle_lines_v1(d->'genjutsu_facts',p_roster);
     -- Fatti congelati nel report prima del suo hash; nessuna lettura DB nel formatter IMMUTABLE.
     suiton:=d#>'{suiton_facts,suiton_server}';
     IF jsonb_typeof(suiton)='object' THEN
       SELECT value->>'display_name' INTO target_name FROM jsonb_array_elements(p_roster)
         WHERE value->>'actor_id'=d#>>'{suiton_facts,target_actor_id}';
       IF target_name IS NOT NULL THEN
         line:=actor_name||' → '||target_name||' · '||coalesce(suiton->>'technique_name','Tecnica Suiton');
         IF d->>'state'='superflua' THEN
           line:=line||': azione non eseguita';
         ELSE
           forced:=suiton->'forced_displacement';
           IF jsonb_typeof(forced)='object' THEN
             IF suiton->'effect_requested'='false'::jsonb THEN
               line:=line||': trascinamento non richiesto';
             ELSIF forced->'applied'='true'::jsonb AND jsonb_typeof(forced->'distance_m')='number' THEN
               line:=line||': trascinamento di '||(forced->>'distance_m')||' m';
             ELSE
               line:=line||': trascinamento non applicato';
               line:=line||CASE suiton->>'secondary_reason'
                 WHEN 'not_full_unnegated_hit' THEN ' (colpo non pieno o negato)'
                 WHEN 'target_inoperative' THEN ' (bersaglio fuori combattimento)'
                 WHEN 'caster_inoperative' THEN ' (esecutore fuori combattimento)'
                 WHEN 'caster_body_unavailable' THEN ' (esecutore non presente sulla mappa)'
                 WHEN 'body_unavailable' THEN ' (bersaglio non presente sulla mappa)'
                 WHEN 'no_legal_prefix' THEN ' (nessun tratto libero percorribile)'
                 ELSE '' END;
             END IF;
           ELSIF suiton->'secondary_applied'='true'::jsonb
             AND jsonb_typeof(suiton->'movement_budget_delta_m')='number'
             AND (suiton->>'movement_budget_delta_m')::numeric<>0 THEN
             line:=line||': variazione applicata al budget di movimento '||(suiton->>'movement_budget_delta_m')||' m';
           ELSIF suiton->'secondary_applied'='false'::jsonb THEN
             line:=line||': penalità di movimento non applicata';
           ELSE
             line:=line||': nessuna applicazione secondaria registrata';
           END IF;
           IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(suiton->'lifecycle','[]'::jsonb)) AS e(value)
             WHERE value->'expired'='true'::jsonb OR value->>'event_kind'='termination') THEN
             line:=line||' · effetto terminato';
           END IF;
         END IF;
         lines:=lines||jsonb_build_array(line);
       END IF;
     END IF;
     -- Effetti temporanei elementali: solo fatti congelati e nomi riconosciuti.
     elemental:=d#>'{elemental_facts,elemental_server}';
     IF jsonb_typeof(elemental)='object' AND elemental->>'technique_name' IN ('Soffio di brace','Scarica') THEN
       SELECT value->>'display_name' INTO target_name FROM jsonb_array_elements(p_roster)
         WHERE value->>'actor_id'=d->>'target';
       IF target_name IS NOT NULL THEN
         line:=actor_name||' → '||target_name||' · '||(elemental->>'technique_name');
         label:=CASE elemental->>'technique_name' WHEN 'Soffio di brace' THEN 'Bruciatura lieve' ELSE 'Apertura difensiva −1' END;
         IF d->>'state'='superflua' OR elemental->>'execution'='not_executed' THEN
           line:=line||': azione non eseguita';
         ELSE
           IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(elemental->'lifecycle','[]'::jsonb)) e(value)
             WHERE value->>'event_kind'='application' AND value->'applied'='true'::jsonb) THEN
             line:=line||': '||label||' applicata';
           ELSIF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(elemental->'lifecycle','[]'::jsonb)) e(value)
             WHERE value->>'event_kind' IN ('application','rejected') AND value->'applied'='false'::jsonb) THEN
             line:=line||': '||label||' non applicata';
           ELSE
             line:=line||': nessuna applicazione secondaria registrata';
           END IF;
           FOR item IN SELECT value FROM jsonb_array_elements(coalesce(elemental->'lifecycle','[]'::jsonb)) LOOP
             IF item->>'event_kind'='save' AND item->'save_attempted'='true'::jsonb
               AND jsonb_typeof(item->'save_roll')='number' AND jsonb_typeof(item->'save_success')='boolean' THEN
               line:=line||' · tiro salvezza '||(item->>'save_roll')||CASE WHEN (item->>'save_success')::boolean THEN ': riuscito' ELSE ': fallito' END;
               IF jsonb_typeof(item->'damage_applied')='number' THEN line:=line||' · danno da bruciatura '||(item->>'damage_applied'); END IF;
             ELSIF item->>'event_kind'='comparison' AND jsonb_typeof(item->'hit_only_delta')='number' THEN
               line:=line||' · modificatore al confronto difensivo '||(item->>'hit_only_delta');
             END IF;
           END LOOP;
           IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(elemental->'lifecycle','[]'::jsonb)) e(value)
             WHERE value->'expired'='true'::jsonb OR value->'ended'='true'::jsonb OR value->>'event_kind'='termination') THEN
             line:=line||' · effetto terminato';
           END IF;
         END IF;
         lines:=lines||jsonb_build_array(line);
       END IF;
     END IF;

     -- Altre offensive: soltanto effetti e numeri già congelati nel report.
     -- Il nome proviene dalla proiezione della fonte validata; nessun testo libero.
     IF jsonb_typeof(elemental)='object' AND elemental->>'technique_name'='Grande sfondamento' THEN
       SELECT value->>'display_name' INTO target_name FROM jsonb_array_elements(p_roster) WHERE value->>'actor_id'=d->>'target';
       IF target_name IS NOT NULL THEN
         line:=actor_name||' → '||target_name||' · Grande sfondamento';
         forced:=elemental->'forced_displacement';
         IF d->>'state'='superflua' OR elemental->>'execution'='not_executed' THEN
           line:=line||': azione non eseguita';
         ELSIF elemental->'effect_requested'='false'::jsonb THEN
           line:=line||': spinta non richiesta';
         ELSIF jsonb_typeof(forced)='object' AND forced->'applied'='true'::jsonb
           AND jsonb_typeof(forced->'distance_m')='number'
           AND (forced->>'distance_m')::numeric>0 AND (forced->>'distance_m')::numeric<=3 THEN
           line:=line||': spinta applicata di '||(forced->>'distance_m')||' m';
           IF forced->'collision_damage'='0'::jsonb THEN line:=line||' · nessun danno da collisione';END IF;
         ELSIF jsonb_typeof(forced)='object' AND forced->'applied'='false'::jsonb THEN
           line:=line||': spinta non applicata';
         ELSE
           line:=NULL;
         END IF;
         IF line IS NOT NULL THEN lines:=lines||jsonb_build_array(line);END IF;
       END IF;
     ELSIF jsonb_typeof(elemental)='object' AND elemental->>'technique_name' IN ('Lama di vento','Lancia di fulmine','Proiettile di roccia') THEN
       IF jsonb_typeof(outcome->'children')='array' THEN effect_targets:=outcome->'children';
       ELSE effect_targets:=jsonb_build_array(outcome||jsonb_build_object('target_actor_id',d->'target'));END IF;
       FOR result_item IN SELECT value FROM jsonb_array_elements(effect_targets) LOOP
         SELECT value->>'display_name' INTO target_name FROM jsonb_array_elements(p_roster) WHERE value->>'actor_id'=result_item->>'target_actor_id';
         IF target_name IS NULL THEN CONTINUE;END IF;
         offensive:=result_item#>'{raw,elemental_offensive}';
         IF jsonb_typeof(offensive) IS DISTINCT FROM 'object' OR offensive->'damage_margin_changed' IS DISTINCT FROM 'false'::jsonb THEN CONTINUE;END IF;
         line:=actor_name||' → '||target_name||' · '||(elemental->>'technique_name');
         IF elemental->>'technique_name' IN ('Lama di vento','Lancia di fulmine') AND offensive->'accuracy_delta' IN ('0'::jsonb,'1'::jsonb) THEN
           line:=line||CASE WHEN offensive->'accuracy_delta'='1'::jsonb THEN ': +1 al confronto per colpire' ELSE ': nessun bonus al confronto per colpire applicato' END||' · margine del danno invariato';
         ELSIF elemental->>'technique_name'='Proiettile di roccia' AND offensive->'parry_reduction_bypassed' IN ('0'::jsonb,'1'::jsonb,'2'::jsonb) THEN
           line:=line||': riduzione della Parata ignorata '||(offensive->>'parry_reduction_bypassed');
         ELSE
           line:=NULL;
         END IF;
         IF line IS NOT NULL THEN lines:=lines||jsonb_build_array(line);END IF;
       END LOOP;
     END IF;

   END LOOP;
   report_view:=jsonb_build_object('report_id',report->'id','title','Risultati del round','lines',lines);
 END IF;
 RETURN jsonb_build_object('schema_version','combat-panel-round-details/1','round_id',rid,'declarations',declarations,'report',report_view);
END $function$

